import React from 'react';
import { Link } from 'react-router-dom';
import { useTheme } from '../context/ThemeContext';

const Footer = () => {
  const { isDarkMode } = useTheme();

  return (
    <footer className={`relative overflow-hidden mt-auto ${isDarkMode ? 'bg-gray-950' : 'bg-slate-800'}`}>
      {/* Animated Gradient Background - Conditional based on theme */}
      <div className={`absolute inset-0 ${isDarkMode ? 'bg-gradient-to-br from-gray-900 via-gray-800 to-gray-900' : 'bg-gradient-to-br from-slate-800 via-slate-700 to-slate-800'}`}></div>
      
      {/* Animated Background Pattern */}
      <div className={`absolute inset-0 ${isDarkMode ? 'opacity-30' : 'opacity-20'}`}>
        <div className="absolute inset-0 bg-gradient-to-r from-primary-500/10 via-secondary-500/10 to-primary-500/10 animate-gradient-shift"></div>
      </div>
      
      {/* Glow Effects - Different for light/dark mode */}
      <div className={`absolute top-0 left-1/4 w-96 h-96 rounded-full blur-3xl ${isDarkMode ? 'bg-primary-500/20' : 'bg-primary-500/15'}`}></div>
      <div className={`absolute bottom-0 right-1/4 w-96 h-96 rounded-full blur-3xl ${isDarkMode ? 'bg-secondary-500/20' : 'bg-secondary-500/15'}`}></div>

      <div className="relative z-10 container mx-auto px-4 py-16">
        <div className="grid md:grid-cols-4 gap-12">
          {/* Company Info */}
          <div className="col-span-2 md:col-span-1 group">
            <div className="flex items-center space-x-3 mb-6">
              <div className="relative w-12 h-12">
                <div className="absolute inset-0 bg-gradient-to-br from-primary-500 to-secondary-500 rounded-full transform group-hover:scale-110 transition-transform duration-500"></div>
                <div className="absolute inset-0 flex items-center justify-center">
                  <span className="text-white font-bold text-xl drop-shadow-lg">M</span>
                </div>
                {/* Glow */}
                <div className="absolute inset-0 bg-gradient-to-br from-primary-500 to-secondary-500 rounded-full blur-xl opacity-50 group-hover:opacity-100 transition-opacity duration-500"></div>
              </div>
              <span className={`text-2xl font-bold bg-gradient-to-r ${isDarkMode ? 'from-white to-gray-300' : 'from-gray-800 to-gray-600'} bg-clip-text text-transparent`}>MilkMitra</span>
            </div>
            <p className={`text-sm leading-relaxed transition-colors duration-300 ${isDarkMode ? 'text-gray-400 group-hover:text-gray-300' : 'text-gray-600 group-hover:text-gray-800'}`}>
              Fresh dairy products delivered to your doorstep. Pure, healthy, and affordable milk and dairy products for your family.
            </p>
            
            {/* Social Icons */}
            <div className="flex space-x-4 mt-6">
              {['facebook', 'twitter', 'instagram', 'youtube'].map((social) => (
                <a
                  key={social}
                  href="#"
                  className={`w-10 h-10 rounded-full border flex items-center justify-center transform hover:scale-110 transition-all duration-300 hover:text-white hover:bg-gradient-to-br hover:from-primary-500 hover:to-secondary-500 hover:border-transparent ${isDarkMode ? 'bg-gray-800/50 border-gray-700 text-gray-400' : 'bg-white border-gray-300 text-gray-600 hover:shadow-lg'}`}
                >
                  <span className="text-sm font-bold">{social[0].toUpperCase()}</span>
                </a>
              ))}
            </div>
          </div>

          {/* Quick Links */}
          <div className="group">
            <h3 className={`text-xl font-bold mb-6 bg-gradient-to-r bg-clip-text text-transparent ${isDarkMode ? 'from-white to-gray-300' : 'from-gray-800 to-gray-600'}`}>
              Quick Links
            </h3>
            <ul className="space-y-3">
              {[
                { to: '/', label: 'Home' },
                { to: '/products', label: 'Products' },
                { to: '/cart', label: 'Cart' },
                { to: '/login', label: 'Login' }
              ].map((link) => (
                <li key={link.to}>
                  <Link 
                    to={link.to} 
                    className={`hover:translate-x-2 inline-flex items-center transition-all duration-300 group/link ${isDarkMode ? 'text-gray-400 hover:text-white' : 'text-gray-600 hover:text-gray-900'}`}
                  >
                    <span className="w-0 group-hover/link:w-2 h-0.5 bg-gradient-to-r from-primary-500 to-secondary-500 mr-0 group-hover/link:mr-2 transition-all duration-300"></span>
                    {link.label}
                  </Link>
                </li>
              ))}
            </ul>
          </div>

          {/* Products */}
          <div className="group">
            <h3 className={`text-xl font-bold mb-6 bg-gradient-to-r bg-clip-text text-transparent ${isDarkMode ? 'from-white to-gray-300' : 'from-gray-800 to-gray-600'}`}>
              Products
            </h3>
            <ul className="space-y-3">
              {[
                { to: '/products?category=milk', label: 'Fresh Milk' },
                { to: '/products?category=ghee', label: 'Desi Ghee' },
                { to: '/products?category=paneer', label: 'Paneer' },
                { to: '/products?category=curd', label: 'Curd' },
                { to: '/products?category=cheese', label: 'Cheese' }
              ].map((link) => (
                <li key={link.to}>
                  <Link 
                    to={link.to} 
                    className={`hover:translate-x-2 inline-flex items-center transition-all duration-300 group/link ${isDarkMode ? 'text-gray-400 hover:text-white' : 'text-gray-600 hover:text-gray-900'}`}
                  >
                    <span className="w-0 group-hover/link:w-2 h-0.5 bg-gradient-to-r from-primary-500 to-secondary-500 mr-0 group-hover/link:mr-2 transition-all duration-300"></span>
                    {link.label}
                  </Link>
                </li>
              ))}
            </ul>
          </div>

          {/* Contact */}
          <div className="group">
            <h3 className={`text-xl font-bold mb-6 bg-gradient-to-r bg-clip-text text-transparent ${isDarkMode ? 'from-white to-gray-300' : 'from-gray-800 to-gray-600'}`}>
              Contact Us
            </h3>
            <ul className="space-y-4">
              {[
                { icon: '📍', text: 'Mumbai, Maharashtra, India' },
                { icon: '📞', text: '+91 98765 43210' },
                { icon: '✉️', text: 'support@milkmitra.com' }
              ].map((contact, index) => (
                <li 
                  key={index}
                  className={`flex items-center space-x-3 transition-all duration-300 group/item cursor-pointer ${isDarkMode ? 'text-gray-400 hover:text-white' : 'text-gray-600 hover:text-gray-900'}`}
                >
                  <span className={`w-10 h-10 rounded-full border flex items-center justify-center transform group-hover/item:scale-110 transition-all duration-300 group-hover/item:bg-gradient-to-br group-hover/item:from-primary-500 group-hover/item:to-secondary-500 group-hover/item:border-transparent ${isDarkMode ? 'bg-gray-800/50 border-gray-700' : 'bg-white border-gray-300'}`}>
                    {contact.icon}
                  </span>
                  <span className="text-sm">{contact.text}</span>
                </li>
              ))}
            </ul>
          </div>
        </div>

        {/* Modern Divider */}
        <div className="relative mt-12 mb-8">
          <div className="absolute inset-0 flex items-center">
            <div className={`w-full border-t ${isDarkMode ? 'border-gray-700/50' : 'border-gray-300/50'}`}></div>
          </div>
          <div className="relative flex justify-center">
            <div className={`px-4 ${isDarkMode ? 'bg-gray-900' : 'bg-white'}`}>
              <div className="w-3 h-3 rounded-full bg-gradient-to-r from-primary-500 to-secondary-500 animate-pulse"></div>
            </div>
          </div>
        </div>

        {/* Copyright */}
        <div className="text-center">
          <p className={`text-sm ${isDarkMode ? 'text-gray-500' : 'text-gray-400'}`}>
            <span className={`bg-gradient-to-r bg-clip-text text-transparent ${isDarkMode ? 'from-gray-400 to-gray-300' : 'from-gray-500 to-gray-400'}`}>
              © {new Date().getFullYear()} MilkMitra. All rights reserved. Fresh Dairy Products Delivery
            </span>
          </p>
        </div>
      </div>
    </footer>
  );
};

export default Footer;
